      // A pathless app can't be opened standalone, so fall back to the panel.
      const newWindow = event && (event.ctrlKey || event.metaKey)
      if (newWindow && app.path) {
        this.$ui.openNewWindowAppPanel(app)
        return
      }
      this.$ui.openWorkspace(app)
    },
